mapper.select:
SELECT DISTINCT group_id
FROM crawler_data
WHERE crawler_id = #{crawlerId}
LIMIT #{offset} , #{pageSize}

SELECT COUNT(DISTINCT group_id)
FROM crawler_data
WHERE crawler_id = #{crawlerId}

SELECT
JSON_MERGE_PATCH(
    JSON_OBJECT('group_id', cd.group_id),
    JSON_OBJECTAGG(cdf.field_name, cd.data)
) AS field_map
FROM
crawler_data cd
LEFT JOIN
crawler_data_field cdf ON cdf.field_id = cd.fieldid








                        AND cd.created_at >= #{value}



                        AND cd.created_at < #{value}



                        AND EXISTS (
                        SELECT 1
                        FROM crawler_data cd_sub
                        INNER JOIN crawler_data_field cdf_sub
                        ON cd_sub.fieldid = cdf_sub.field_id
                        WHERE
                        cd_sub.group_id = cd.group_id
                        AND cdf_sub.field_name = #{key}
                        AND cd_sub.data = #{value}
                        )






        AND cd.crawler_id = #{crawlerId}


GROUP BY
cd.group_id

    LIMIT #{len}, #{index};

SELECT
count(DISTINCT cd.group_id)
FROM
crawler_data cd
LEFT JOIN
crawler_data_field cdf ON cdf.field_id = cd.fieldid








                        AND cd.created_at >= #{value}



                        AND cd.created_at < #{value}



                        AND EXISTS (
                        SELECT 1
                        FROM crawler_data cd_sub
                        INNER JOIN crawler_data_field cdf_sub
                        ON cd_sub.fieldid = cdf_sub.field_id
                        WHERE
                        cd_sub.group_id = cd.group_id
                        AND cdf_sub.field_name = #{key}
                        AND cd_sub.data = #{value}
                        )






        AND cd.crawler_id = #{crawlerId}

SELECT





                SUM(
                IF(
                cdf.field_name = #{field} AND cd.data = #{value},
                1,
                0
                )
                ) AS `${field}_${value}`,




FROM
crawler_data cd
INNER JOIN
crawler_data_field cdf ON cdf.field_id = cd.fieldid



        AND cd.created_at >= #{start}


        AND cd.created_at < #{end}




            AND (





                        cdf.field_name = #{condition.field}
                        AND cd.data = #{condition.value}



                        cdf.field_name = #{condField}
                        AND cd.data = #{condEntry}



            )



        AND cd.crawler_id = #{crawlerId}

SELECT temp.group_id FROM (
SELECT #{groupid} AS group_id FROM DUAL
) temp LEFT JOIN crawler_data cd ON temp.group_id = cd.group_id WHERE cd.group_id IS NULL
